            for (int j = 0; j < 2; j++) {
                int b = 0;
                for (int di = 0; di < 2; di++)
                    for (int dj = 0; dj < 2; dj++)
                        b += grid[i + di][j + dj] == 'B';
                if (b != 2) return true;
            }
        }
        return false;
    }
};

