        for (int i = 0; i < 2; i++)
            for (int j = 0; j < 2; j++) {
                char c = g[i][j];
                if (g[i][j+1] == c && g[i+1][j] == c && g[i+1][j+1] == c)
                    return true;
            }
        return false;
    }

    public boolean canMakeSquare(char[][] grid) {
