        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++) {
                grid[i][j] = (grid[i][j] == 'B') ? 'W' : 'B';
                boolean res = ok(grid);
                grid[i][j] = (grid[i][j] == 'B') ? 'W' : 'B';
                if (res) return true;
            }
        return false;
